# Analysis: Adding Dynamic Custom Actions to Document Chapter Headings

## Current Architecture Overview

The markdown rendering pipeline flows through:
1. **Document.vue** - Parses content into blocks (code/markdown)
2. **MarkdownViewer.vue** - Renders markdown with heading anchors
3. **ChatEntry.vue** - Container that uses Document component

Currently, headings are rendered as plain HTML with anchor IDs, with no interactive capabilities for custom actions.

## Proposed Solution

### Architecture Pattern: **Heading Action Provider**

Create a flexible system where:
1. **Heading context is injected** into MarkdownViewer via props
2. **Custom action slots/handlers** are passed down from ChatEntry
3. **Action menu** is rendered next to headings dynamically
4. **Multiple use cases** are supported without coupling

## Implementation Plan

### 1. Create `HeadingActionsPlugin` (New Utility)

```js src/utils/headingActionsPlugin.js
// Custom markdown-it plugin to mark headings with metadata
export function createHeadingActionsPlugin() {
  return (md) => {
    const defaultHeadingRenderer = md.renderer.rules.heading_open || function(tokens, idx, options, env, self) {
      return self.renderToken(tokens, idx, options)
    }

    md.renderer.rules.heading_open = function(tokens, idx, options, env, self) {
      const token = tokens[idx]
      const level = parseInt(token.tag[1])
      token.attrSet('data-heading-level', level.toString())
      token.attrSet('data-heading-interactive', 'true')
      token.attrSet('class', 'heading-interactive group relative')
      return defaultHeadingRenderer(tokens, idx, options, env, self)
    }
  }
}
```

### 2. Enhance MarkdownViewer Component

```vue src/components/MarkdownViewer.vue
<script setup>
import { full as emoji } from 'markdown-it-emoji'
import MarkdownIt from 'markdown-it'
import highlight from 'markdown-it-highlightjs'
import InteractiveTable from './InteractiveTable.vue'
import { createHeadingActionsPlugin } from '../utils/headingActionsPlugin'
</script>

<template>
  <div class="text-wrap overflow-y-auto prose max-w-full">
    <div class="space-y-4">
      <div 
        v-for="(element, idx) in renderedElements" 
        :key="`element-${idx}`"
        @click="handleClick"
      >
        <div 
          v-if="element.type === 'markdown'"
          v-html="element.content"
          class="relative"
        ></div>

        <InteractiveTable 
          v-else-if="element.type === 'table'"
          :initial-data="element.data"
          :table-index="idx"
          @update-table="handleTableUpdate"
        />
      </div>
    </div>
  </div>
</template>

<script>
import MarkdownIt from 'markdown-it'
import { full as emoji } from 'markdown-it-emoji'
import highlight from 'markdown-it-highlightjs'
import InteractiveTable from './InteractiveTable.vue'
import { createHeadingActionsPlugin } from '../utils/headingActionsPlugin'

function createMd(documentId, includeHeadingActions = false) {
  const md = new MarkdownIt({ html: true, linkify: true, typographer: true })
  md.use(emoji)
  md.use(highlight)

  if (includeHeadingActions) {
    md.use(createHeadingActionsPlugin())
  }

  const defaultHeadingRenderer = md.renderer.rules.heading_open || function(tokens, idx, options, env, self) {
    return self.renderToken(tokens, idx, options)
  }

  md.renderer.rules.heading_open = function(tokens, idx, options, env, self) {
    const token = tokens[idx]
    const inlineToken = tokens[idx + 1]
    if (inlineToken && inlineToken.children) {
      const text = inlineToken.children
        .filter(t => t.type === 'text' || t.type === 'code_inline')
        .map(t => t.content)
        .join('')
      const slug = text
        .toLowerCase()
        .replace(/[^\w\s-]/g, '')
        .trim()
        .replace(/\s+/g, '-')
      const anchor = documentId ? `${documentId}-${slug}` : slug
      token.attrSet('id', anchor)
      token.attrSet('class', 'heading-anchor scroll-mt-4 group relative')
    }
    return defaultHeadingRenderer(tokens, idx, options, env, self)
  }

  // ... rest of markdown-it setup remains the same ...

  return md
}

export default {
  props: {
    text: { type: String, default: '' },
    files: { type: Array, default: null },
    documentId: { type: String, default: '' },
    headingActions: { type: Array, default: null }, // NEW: Pass actions from parent
    includeHeadingMenu: { type: Boolean, default: false } // NEW: Enable heading interactions
  },
  emits: ['add-file', 'table-updated', 'heading-action'], // NEW: Emit heading actions
  components: {
    InteractiveTable
  },
  data() {
    return {
      renderedElements: [],
      activeHeadingId: null
    }
  },
  computed: {
    sanitizedText() {
      let text = ''
      if (this.text) {
        text = this.text
          .replace('```thymeleaf', '```html')
          .replace('```md', '')
      }
      return text
    }
  },
  watch: {
    text() {
      this.renderContent()
    }
  },
  mounted() {
    this.renderContent()
    this.attachHeadingListeners()
  },
  methods: {
    renderContent() {
      try {
        const md = createMd(this.documentId, this.includeHeadingMenu)
        const textWithLinks = this.sanitizedText.replace(
          /`((?:\/[^\s:]+)+)(?::(\d+))?`/g,
          (match, filePath, lineNumber) => {
            const slashCount = (filePath.match(/\//g) || []).length
            if (slashCount < 2) return match
            const lineInfo = lineNumber ? `:${lineNumber}` : ''
            return `<a class="file-link btn btn-link" href="${filePath}${lineInfo}">${filePath}${lineInfo}</a>`
          }
        )
        const rendered = md.render(textWithLinks)
        this.parseElements(rendered)
      } catch (ex) {
        console.error("Message can't be rendered", this.text)
        this.renderedElements = []
      }
    },
    attachHeadingListeners() {
      this.$nextTick(() => {
        if (!this.includeHeadingMenu) return

        const headings = document.querySelectorAll('[data-heading-interactive]')
        headings.forEach(heading => {
          heading.addEventListener('mouseenter', (e) => this.onHeadingHover(e, heading))
        })
      })
    },
    onHeadingHover(event, headingEl) {
      const level = headingEl.getAttribute('data-heading-level')
      const text = headingEl.textContent
      this.activeHeadingId = headingEl.id
      this.$emit('heading-hover', { level, text, id: headingEl.id })
    },
    parseElements(html) {
      // ... existing parseElements logic remains the same ...
    },
    handleTableUpdate(payload) {
      this.$emit('table-updated', payload)
    },
    handleClick(event) {
      const btn = event.target.closest('.file-path-upload-btn')
      if (!btn) return
      event.preventDefault()
      event.stopPropagation()
      const filePath = btn.getAttribute('data-file-path')
      if (filePath) {
        this.$emit('add-file', filePath)
      }
    }
  }
}
</script>
```

### 3. Create `HeadingActionMenu` Component (New)

```vue src/components/document/HeadingActionMenu.vue
<script setup>
import ChatIcon from '../chat/ChatIcon.vue'
</script>

<template>
  <div 
    class="absolute right-0 top-0 opacity-0 group-hover:opacity-100 transition-opacity"
