  >
    <div class="dropdown dropdown-end">
      <button 
        tabindex="0" 
        class="btn btn-ghost btn-xs"
        :title="`Actions for: ${headingText}`"
      >
        <i class="fa-solid fa-ellipsis-v"></i>
      </button>
      <ul 
        tabindex="0" 
        class="dropdown-content menu rounded-box shadow bg-base-300 z-50"
      >
        <li v-for="action in actions" :key="action.id">
          <a @click.prevent="handleAction(action)">
            <i :class="action.icon" v-if="action.icon"></i>
            {{ action.label }}
          </a>
        </li>
      </ul>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    actions: { type: Array, default: null },
    headingText: { type: String, default: '' },
    headingLevel: { type: Number, default: 1 },
    headingId: { type: String, default: '' }
  },
  emits: ['action-selected'],
  methods: {
    handleAction(action) {
      this.$emit('action-selected', {
        actionId: action.id,
        headingText: this.headingText,
        headingLevel: this.headingLevel,
        headingId: this.headingId,
        payload: action.payload || null
      })
    }
  }
}
</script>
```

### 4. Update Document Component

```vue src/components/document/Document.vue
<script setup>
import MarkdownViewer from '../MarkdownViewer.vue'
import Code from '../Code.vue'
import HeadingActionMenu from './HeadingActionMenu.vue'
</script>

<template>
  <div class="flex flex-col @container/document">
    <div v-for="block in blocks" :key="block.hash">
      <MarkdownViewer
        :files="files"
