<script>
// ... existing imports and functions ...

export default {
  props: [
    'content', 'files', 'project', 'chat', 'loading', 
    'documentId', 'message',
    'headingActions', // NEW: Custom actions for headings
    'includeHeadingMenu' // NEW: Enable heading menu
  ],
  emits: [
    'generate-code', 'reload-file', 'open-file', 'save-file', 
    'add-file', 'edit-message', 'sub-task',
    'heading-action' // NEW: Emit heading actions to parent
  ],
  data() {
    return {}
  },
  computed: {
    blocks() {
      return parseContent(this.content || '', this.loading)
    },
    docProject() {
      return this.project || this.$project
    }
  },
  methods: {
    handleHeadingAction(actionData) {
      this.$emit('heading-action', actionData)
    }
  }
}
</script>
```

### 5. Update ChatEntry Component

```vue src/components/ChatEntry.vue
