      this.$emit('chapter-action', actionData)
    },

    createSubtaskFromChapter(title, level) {
      this.$emit('sub-task', {
        title: title,
        level: level,
        message: this.message
      })
    },

    expandChapterSection(headingId) {
      const element = document.getElementById(headingId)
      if (element) {
        element.scrollIntoView({ behavior: 'smooth', block: 'start' })
      }
    },

    generateChapterSummary(title, level) {
      // Implementation depends on your backend
      console.log(`Generating summary for: ${title}`)
    }
  }
}
</script>
```

## Key Benefits of This Architecture

| Aspect | Benefit |
|--------|---------|
| **Decoupling** | MarkdownViewer remains generic; actions defined by parent component |
| **Reusability** | Same MarkdownViewer used in different contexts with different actions |
| **Flexibility** | Easy to add/remove/modify actions without touching core components |
| **Scalability** | New use cases can define their own action sets |
| **UX** | Actions appear on hover, minimal visual clutter |

## Usage in Other Contexts

If you need the same MarkdownViewer elsewhere **without** chapter actions:

```vue
<MarkdownViewer
  :text="content"
  :documentId="docId"
  :include-heading-menu="false"
/>
```

If you need different actions in another component:

```vue
<Document
  :content="messageContent"
  :include-heading-menu="true"
  :heading-actions="myCustomActions"
  @heading-action="handleMyCustomAction"
/>
```

This approach maintains separation of concerns while enabling rich interactions where needed.

