## 3. Update MarkdownViewer Component

```vue src/components/MarkdownViewer.vue
<script setup>
import { full as emoji } from 'markdown-it-emoji'
import MarkdownIt from 'markdown-it'
import highlight from 'markdown-it-highlightjs'
import InteractiveTable from './InteractiveTable.vue'
import HeadingActionMenu from './document/HeadingActionMenu.vue'
import { createHeadingActionsPlugin } from '../utils/headingActionsPlugin'
</script>

<template>
  <div class="text-wrap overflow-y-auto prose max-w-full">
    <div class="space-y-4">
      <div 
        v-for="(element, idx) in renderedElements" 
        :key="`element-${idx}`"
        @click="handleClick"
      >
        <div 
          v-if="element.type === 'markdown'"
          v-html="element.content"
          class="relative"
        ></div>

        <InteractiveTable 
          v-else-if="element.type === 'table'"
          :initial-data="element.data"
          :table-index="idx"
          @update-table="handleTableUpdate"
        />
      </div>
    </div>
  </div>
</template>

<script>
import MarkdownIt from 'markdown-it'
import { full as emoji } from 'markdown-it-emoji'
import highlight from 'markdown-it-highlightjs'
import InteractiveTable from './InteractiveTable.vue'
import { createHeadingActionsPlugin } from '../utils/headingActionsPlugin'

function createMd(documentId, includeHeadingActions) {
  const md = new MarkdownIt({ html: true, linkify: true, typographer: true })
  md.use(emoji)
  md.use(highlight)

  if (includeHeadingActions) {
    md.use(createHeadingActionsPlugin())
  }

  const defaultHeadingRenderer = md.renderer.rules.heading_open || function(tokens, idx, options, env, self) {
    return self.renderToken(tokens, idx, options)
  }

  md.renderer.rules.heading_open = function(tokens, idx, options, env, self) {
    const token = tokens[idx]
    const inlineToken = tokens[idx + 1]

    if (inlineToken && inlineToken.children) {
      const text = inlineToken.children
        .filter(t => t.type === 'text' || t.type === 'code_inline')
        .map(t => t.content)
        .join('')
      const slug = text
        .toLowerCase()
        .replace(/[^\w\s-]/g, '')
        .trim()
        .replace(/\s+/g, '-')
      const anchor = documentId ? `${documentId}-${slug}` : slug

      if (!includeHeadingActions) {
        token.attrSet('class', 'heading-anchor scroll-mt-4')
      }
      token.attrSet('id', anchor)
    }

    return defaultHeadingRenderer(tokens, idx, options, env, self)
  }

  md.core.ruler.push('table_marker', (state) => {
    let rowIdx = 0
    for (let i = 0; i < state.tokens.length; i++) {
      const token = state.tokens[i]
      if (token.type === 'table_open') {
        token.attrSet('data-interactive-table', 'true')
        rowIdx = 0
      }
      if (token.type === 'tr_open') {
        token.attrSet('data-row', rowIdx.toString())
        rowIdx++
      }
      if (token.type === 'th_open' || token.type === 'td_open') {
        const colIdx = token.map ? state.tokens.slice(0, i).filter(t => t.type === token.type && t.map && t.map[0] === token.map[0]).length : 0
        token.attrSet('data-col', colIdx.toString())
      }
    }
  })

  const defaultFenceRenderer = md.renderer.rules.fence || function(tokens, idx, options, env, self) {
    return self.renderToken(tokens, idx, options)
  }

  md.renderer.rules.fence = function(tokens, idx, options, env, self) {
    const token = tokens[idx]
    const info = token.info ? token.info.trim() : ''
    const infoMatch = info.match(/^(\w+)\s+([\w\-_.\/]+)$/)
    const filePath = infoMatch ? infoMatch[2] : null
    const rendered = defaultFenceRenderer(tokens, idx, options, env, self)

    if (!filePath) return rendered

    const slug = filePath
      .toLowerCase()
      .replace(/[^\w\s\-./]/g, '')
      .trim()
      .replace(/[\s/]+/g, '-')
    const anchor = documentId ? `${documentId}-${slug}` : slug
    return `<div id="${anchor}" class="code-block-anchor scroll-mt-4">${rendered}</div>`
  }

  return md
}

const FILE_PATH_REGEX = /(?<=^|[\s(,>])((?:\.{1,2}\/|\/)?(?:[\w\-_.]+\/)+[\w\-_.]+\.(?:js|ts|vue|py|java|cpp|c|h|cs|go|rb|rs|php|html|css|scss|json|yaml|yml|md|txt|sh|bash|env|toml|xml|sql|graphql|proto|ipynb|jsx|tsx|mjs|cjs|svelte|kotlin|swift|dart))(?=[\s),<]|$)/g

function addFileUploadIcons(html) {
  return html.replace(
    FILE_PATH_REGEX,
    (match) =>
      `<span
        class="file-path-upload-btn underline ml-1 cursor-pointer inline-flex items-center align-middle"
        data-file-path="${match}"
        title="Add '${match}' to chat files"
      ><i class="fa-solid fa-file-arrow-up"></i>&nbsp;${match}</span>`
  )
}

function parseTableFromHtml(tableHtml) {
  if (typeof document === 'undefined') return null
  const parser = new DOMParser()
  const doc = parser.parseFromString(tableHtml, 'text/html')
  const table = doc.querySelector('table')
  if (!table) return null

  const data = []
  const rows = table.querySelectorAll('tr')

  rows.forEach(tr => {
    const cells = tr.querySelectorAll('td, th')
    const row = Array.from(cells).map(cell => cell.textContent.trim())
    if (row.length > 0) data.push(row)
  })

  return data.length > 0 ? data : null
}

export default {
  props: {
    text: { type: String, default: '' },
    files: { type: Array, default: null },
    documentId: { type: String, default: '' },
    headingActions: { type: Array, default: null },
    includeHeadingMenu: { type: Boolean, default: false }
  },
  emits: ['add-file', 'table-updated', 'heading-action'],
  components: {
    InteractiveTable,
    HeadingActionMenu
  },
  data() {
    return {
      renderedElements: [],
      headingMetadata: {}
    }
  },
  computed: {
    sanitizedText() {
      let text = ''
      if (this.text) {
        text = this.text
          .replace('```thymeleaf', '```html')
          .replace('```md', '')
      }
      return text
    }
  },
  watch: {
    text() {
      this.renderContent()
    },
    includeHeadingMenu() {
      this.renderContent()
    }
  },
  mounted() {
    this.renderContent()
    this.attachHeadingListeners()
  },
  updated() {
    this.attachHeadingListeners()
  },
  methods: {
    renderContent() {
      try {
        const md = createMd(this.documentId, this.includeHeadingMenu)
        const textWithLinks = this.sanitizedText.replace(
          /`((?:\/[^\s:]+)+)(?::(\d+))?`/g,
          (match, filePath, lineNumber) => {
            const slashCount = (filePath.match(/\//g) || []).length
            if (slashCount < 2) return match
            const lineInfo = lineNumber ? `:${lineNumber}` : ''
            return `<a class="file-link btn btn-link" href="${filePath}${lineInfo}">${filePath}${lineInfo}</a>`
          }
        )
        const rendered = md.render(textWithLinks)
        this.parseElements(rendered)
      } catch (ex) {
        console.error("Message can't be rendered", this.text)
        this.renderedElements = []
      }
    },
    parseElements(html) {
      const elements = []
      const tableRegex = /<table[^>]*>[\s\S]*?<\/table>/g
      let lastIndex = 0
      let match

      const tables = []
      while ((match = tableRegex.exec(html)) !== null) {
        tables.push({
          start: match.index,
          end: match.index + match[0].length,
          html: match[0],
          data: parseTableFromHtml(match[0])
        })
      }

      tables.forEach((table, idx) => {
        if (table.start > lastIndex) {
          const mdHtml = html.substring(lastIndex, table.start).trim()
          if (mdHtml) {
            elements.push({
              type: 'markdown',
              content: addFileUploadIcons(this.wrapHeadingsWithMenu(mdHtml))
            })
          }
        }

        if (table.data && table.data.length > 0) {
          elements.push({
            type: 'table',
            data: table.data
          })
        }

        lastIndex = table.end
      })

      if (lastIndex < html.length) {
        const mdHtml = html.substring(lastIndex).trim()
        if (mdHtml) {
          elements.push({
            type: 'markdown',
            content: addFileUploadIcons(this.wrapHeadingsWithMenu(mdHtml))
          })
        }
      }

      this.renderedElements = elements.length > 0 ? elements : [{ 
        type: 'markdown', 
        content: addFileUploadIcons(this.wrapHeadingsWithMenu(html))
      }]
    },
    wrapHeadingsWithMenu(html) {
      if (!this.includeHeadingMenu || !this.headingActions) return html

      return html.replace(
        /(<h[1-6][^>]*data-heading-interactive="true"[^>]*id="([^"]*)"[^>]*data-heading-text="([^"]*)"[^>]*>)/g,
        (match, opening, id, text) => {
          const level = match.match(/h([1-6])/)[1]
          this.headingMetadata[id] = { text, level }
          return `${opening}<span class="heading-action-wrapper" data-heading-id="${id}"></span>`
        }
      )
    },
    attachHeadingListeners() {
      if (!this.includeHeadingMenu) return

      this.$nextTick(() => {
        Object.entries(this.headingMetadata).forEach(([id, metadata]) => {
          const heading = document.getElementById(id)
          if (!heading) return

          const wrapper = heading.querySelector('[class*="heading-action-wrapper"]')
          if (!wrapper) {
            const newWrapper = document.createElement('span')
            newWrapper.className = 'heading-action-wrapper'
            newWrapper.dataset.headingId = id
            heading.appendChild(newWrapper)
          }
        })
      })
    },
    handleTableUpdate(payload) {
      this.$emit('table-updated', payload)
    },
    handleClick(event) {
      const btn = event.target.closest('.file-path-upload-btn')
      if (!btn) return
      event.preventDefault()
      event.stopPropagation()
      const filePath = btn.getAttribute('data-file-path')
      if (filePath) {
        this.$emit('add-file', filePath)
      }
    },
    onHeadingAction(actionData) {
      this.$emit('heading-action', actionData)
    }
  }
}
</script>
