// Custom markdown-it plugin to mark headings with metadata
export function createHeadingActionsPlugin() {
  return (md) => {
    const defaultHeadingRenderer = md.renderer.rules.heading_open || function(tokens, idx, options, env, self) {
      return self.renderToken(tokens, idx, options)
    }

    md.renderer.rules.heading_open = function(tokens, idx, options, env, self) {
      const token = tokens[idx]
      const level = parseInt(token.tag[1])
      const inlineToken = tokens[idx + 1]

      if (inlineToken && inlineToken.children) {
        const text = inlineToken.children
          .filter(t => t.type === 'text' || t.type === 'code_inline')
          .map(t => t.content)
          .join('')

        token.attrSet('data-heading-level', level.toString())
        token.attrSet('data-heading-text', text)
        token.attrSet('data-heading-interactive', 'true')
        token.attrSet('class', 'heading-interactive group relative py-2')
      }

      return defaultHeadingRenderer(tokens, idx, options, env, self)
    }
  }
}

