                :alt="image.alt" 
                :title="image.alt"
              >
                <div class="flex flex-col">
                  <div 
                    class="bg-contain bg-no-repeat bg-center border rounded-md w-12 h-12 md:h-20 md:w-20" 
                    :style="`background-image: url(${image.src})`"
                  ></div>
